import counterReducer, {
  increment,
  decrement,
  incrementByAmount,
  reset
} from './counterSlice';

describe('counter reducer', () => {
  // Always test the initial state
  describe('initial state', () => {
    it('should return the initial state when called with undefined', () => {
      const initialState = { value: 0, status: 'idle' };
      expect(counterReducer(undefined, { type: 'unknown' })).toEqual(initialState);
    });
  });

  // Group tests by action
  describe('increment', () => {
    it('should increment the value by 1', () => {
      const previousState = { value: 5, status: 'idle' };
      expect(counterReducer(previousState, increment())).toEqual({
        value: 6,
        status: 'idle'
      });
    });

    it('should handle increment from zero', () => {
      const initialState = { value: 0, status: 'idle' };
      expect(counterReducer(initialState, increment())).toEqual({
        value: 1,
        status: 'idle'
      });
    });
  });

  describe('decrement', () => {
    it('should decrement the value by 1', () => {
      const previousState = { value: 3, status: 'idle' };
      expect(counterReducer(previousState, decrement())).toEqual({
        value: 2,
        status: 'idle'
      });
    });
  });

  describe('incrementByAmount', () => {
    it('should increment by the specified amount', () => {
      const previousState = { value: 10, status: 'idle' };
      expect(counterReducer(previousState, incrementByAmount(5))).toEqual({
        value: 15,
        status: 'idle'
      });
    });

    it('should handle zero increment', () => {
      const previousState = { value: 7, status: 'idle' };
      expect(counterReducer(previousState, incrementByAmount(0))).toEqual({
        value: 7,
        status: 'idle'
      });
    });
  });
});

// Assuming a todo slice
import todosReducer, {
  todoAdded,
  todoToggled,
  todoDeleted,
  todoUpdated
} from './todosSlice';

describe('todos reducer', () => {
  const initialState = {
    items: [],
    filter: 'all'
  };

  describe('todoAdded', () => {
    it('should add a new todo with correct structure', () => {
      const action = todoAdded({
        id: 'todo-1',
        text: 'Buy groceries',
        completed: false
      });

      const result = todosReducer(initialState, action);

      expect(result.items).toHaveLength(1);
      expect(result.items[0]).toMatchObject({
        id: 'todo-1',
        text: 'Buy groceries',
        completed: false
      });
    });
  });

  describe('todoUpdated', () => {
    it('should update todo text', () => {
      const stateWithTodo = {
        items: [
          { id: 'todo-1', text: 'Old text', completed: false }
        ],
        filter: 'all'
      };

      const action = todoUpdated({
        id: 'todo-1',
        changes: { text: 'New text' }
      });

      const result = todosReducer(stateWithTodo, action);
      expect(result.items[0].text).toBe('New text');
    });

    it('should toggle todo completed status', () => {
      const stateWithTodo = {
        items: [
          { id: 'todo-1', text: 'Task', completed: false }
        ],
        filter: 'all'
      };

      const action = todoToggled('todo-1');
      const result = todosReducer(stateWithTodo, action);

      expect(result.items[0].completed).toBe(true);
    });
  });
});

import usersReducer, {
  userAdded,
  userUpdated,
  userRemoved,
  usersReceived
} from './usersSlice';

describe('users reducer', () => {
  const initialState = {
    ids: [],
    entities: {},
    loading: false
  };

  describe('userAdded', () => {
    it('should add a user to empty state', () => {
      const user = { id: 'user-1', name: 'Alice', email: 'alice@example.com' };
      const result = usersReducer(initialState, userAdded(user));

      expect(result.ids).toContain('user-1');
      expect(result.entities['user-1']).toEqual(user);
    });

    it('should add multiple users with addMany equivalent', () => {
      // Using addOne multiple times works like addMany
      let result = usersReducer(initialState, userAdded({ id: 'u1', name: 'A' }));
      result = usersReducer(result, userAdded({ id: 'u2', name: 'B' }));

      expect(result.ids).toHaveLength(2);
      expect(Object.keys(result.entities)).toHaveLength(2);
    });
  });

  describe('usersReceived', () => {
    it('should replace all users with new set', () => {
      const stateWithUsers = {
        ids: ['old-1'],
        entities: { 'old-1': { id: 'old-1', name: 'Old' } },
        loading: false
      };

      const newUsers = [
        { id: 'new-1', name: 'New One' },
        { id: 'new-2', name: 'New Two' }
      ];

      const result = usersReducer(stateWithUsers, usersReceived(newUsers));

      expect(result.ids).toHaveLength(2);
      expect(result.entities['new-1']).toBeDefined();
      expect(result.entities['old-1']).toBeUndefined();
    });
  });

  describe('userUpdated', () => {
    it('should partially update a user', () => {
      const stateWithUser = {
        ids: ['user-1'],
        entities: { 'user-1': { id: 'user-1', name: 'Alice', role: 'user' } },
        loading: false
      };

      const result = usersReducer(
        stateWithUser,
        userUpdated({ id: 'user-1', changes: { role: 'admin' } })
      );

      expect(result.entities['user-1'].role).toBe('admin');
      expect(result.entities['user-1'].name).toBe('Alice'); // Unchanged
    });
  });

  describe('userRemoved', () => {
    it('should remove a user', () => {
      const stateWithUser = {
        ids: ['user-1'],
        entities: { 'user-1': { id: 'user-1', name: 'Alice' } },
        loading: false
      };

      const result = usersReducer(stateWithUser, userRemoved('user-1'));

      expect(result.ids).not.toContain('user-1');
      expect(result.entities['user-1']).toBeUndefined();
    });
  });
});
